PYTHON_EXE = r"C:\Users\user\AppData\Local\Programs\Python\Python313\python.exe"
GENERATE_SCRIPT = PROJECT_ROOT + r"\generate.py"
RESULT_PATH = PROJECT_ROOT + r"\generated\result.py"
ERROR_FILE = PROJECT_ROOT + r"\generated\prev_nx_error.json"

MAX_NX_ATTEMPTS = 3  # сколько раз пробуем перегенерировать после ошибки в NX

# Таймаут одного subprocess-вызова generate.py. Внутри run_generation —
# до DEFAULT_MAX_ATTEMPTS (3) попыток по 400с таймаута ollama = максимум
# ~1200с на статическую валидацию, плюс запас на IO/валидацию/build_prompt.
GENERATE_SUBPROCESS_TIMEOUT = 1400
# ------------------------------------------------------------------------

#------------------------------------------------------------------------------
# Represents Block Styler application cls
#------------------------------------------------------------------------------
class new_ui:
    # static class members
    theSession = None
    theUI = None
    
    #------------------------------------------------------------------------------
    # Constructor for NX Styler class
    #------------------------------------------------------------------------------
    def __init__(self):
        try:
            self.theSession = NXOpen.Session.GetSession()
            self.theUI = NXOpen.UI.GetUI()
            self.theDlxFileName = PROJECT_ROOT + r"\new_ui.dlx"
            self.theDialog = self.theUI.CreateDialog(self.theDlxFileName)
            self.theDialog.AddApplyHandler(self.apply_cb)
            self.theDialog.AddOkHandler(self.ok_cb)
            self.theDialog.AddUpdateHandler(self.update_cb)
            self.theDialog.AddInitializeHandler(self.initialize_cb)
            self.theDialog.AddDialogShownHandler(self.dialogShown_cb)
        except Exception as ex:
            self.theUI.NXMessageBox.Show("Ошибка", NXOpen.NXMessageBox.DialogType.Error, str(ex))
            raise ex
        
    #------------------------------------------------------------------------------
    # This method launches the dialog to screen
    #------------------------------------------------------------------------------
    def Launch(self):
        dialogResponse = NXOpen.BlockStyler.BlockDialog.DialogResponse.Invalid
        try:
            dialogResponse = self.theDialog.Launch()
        except Exception as ex:
            self.theUI.NXMessageBox.Show("Ошибка", NXOpen.NXMessageBox.DialogType.Error, str(ex))
        return dialogResponse
    
    #------------------------------------------------------------------------------
    # Method Name: Dispose
    #------------------------------------------------------------------------------
    def Dispose(self):
        if self.theDialog != None:
            self.theDialog.Dispose()
            self.theDialog = None
    
    #------------------------------------------------------------------------------
    # Callback Name: initialize_cb
    #------------------------------------------------------------------------------
    def initialize_cb(self):
        try:
            self.group0 = self.theDialog.TopBlock.FindBlock("group0")
            self.multiline_string0 = self.theDialog.TopBlock.FindBlock("multiline_string0")
            self.button0 = self.theDialog.TopBlock.FindBlock("button0")
        except Exception as ex:
            self.theUI.NXMessageBox.Show("Ошибка", NXOpen.NXMessageBox.DialogType.Error, str(ex))
    
    #------------------------------------------------------------------------------
    # Callback Name: dialogShown_cb
    #------------------------------------------------------------------------------
    def dialogShown_cb(self):
        pass
    
    #------------------------------------------------------------------------------
    # Callback Name: apply_cb
    #------------------------------------------------------------------------------
    def apply_cb(self):
        errorCode = 0
        try:
            pass
        except Exception as ex:
            errorCode = 1
            self.theUI.NXMessageBox.Show("Ошибка", NXOpen.NXMessageBox.DialogType.Error, str(ex))
        return errorCode
    
    #------------------------------------------------------------------------------
    # Helper: вывод сообщения в Listing Window
    #------------------------------------------------------------------------------
    def show_in_listing(self, text: str):
        listing = self.theSession.ListingWindow
        listing.Open()
        listing.WriteLine("=" * 80)
        listing.WriteLine("Ошибка генерации модели")
        listing.WriteLine("=" * 80)
        listing.WriteLine(text)
        listing.WriteLine("=" * 80)
        listing.Close()  # закрываем после записи, окно останется открытым

    #------------------------------------------------------------------------------
    # Callback Name: update_cb
    #------------------------------------------------------------------------------
    def update_cb(self, block):
        try:
            if block == self.multiline_string0:
                pass
            
            elif block == self.button0:
                try:
                    lines = self.multiline_string0.GetValue()
                    user_request = "\n".join(lines).strip() if lines else ""
            
                    if not user_request:
                        return 0
            
                    prev_error_text = None   # ошибка исполнения с предыдущей итерации
                    prev_code_text = None    # код, который реально исполнялся и упал
            
                    for attempt in range(1, MAX_NX_ATTEMPTS + 1):
            
                        # --- шаг 1: генерация (в отдельном не-NX процессе) ---
                        args = [PYTHON_EXE, GENERATE_SCRIPT, user_request]
                        if prev_error_text:
                            # передаём ошибку И код, который её вызвал, через JSON-файл
                            # (не через argv — traceback/код содержат кавычки/переносы строк)
                            with open(ERROR_FILE, "w", encoding="utf-8") as f:
                                json.dump(
                                    {"error": prev_error_text, "code": prev_code_text or ""},
                                    f, ensure_ascii=False,
                                )
                            args.append(ERROR_FILE)
            
                        env = os.environ.copy()
                        env["PYTHONIOENCODING"] = "utf-8"
                        env["PYTHONUTF8"] = "1"

                        proc = subprocess.run(
                            args,
                            capture_output=True, text=True, encoding="utf-8", errors="replace",
                            timeout=GENERATE_SUBPROCESS_TIMEOUT,
                            env=env,
                        )

                        if proc.returncode != 0:
                            # генератор не смог выдать даже статически валидный код —
                            # дальше по NX-retry идти бессмысленно, показываем ошибку сразу
                            self.show_in_listing(proc.stderr)
                            return 0
            
                        # --- шаг 2: реальное исполнение в NX (только здесь есть NXOpen) ---
                        with open(RESULT_PATH, "r", encoding="utf-8") as f:
                            code = f.read()
            
                        try:
                            exec(code, {})
                            # Успех – никаких сообщений, выходим из цикла и из callback
                            return 0
                        except Exception as ex:
                            prev_error_text = f"{type(ex).__name__}: {ex}"
                            prev_code_text = code  # именно тот код, что упал — для retry
                            if attempt == MAX_NX_ATTEMPTS:
                                self.show_in_listing(
                                    f"Ошибка выполнения (после {MAX_NX_ATTEMPTS} попыток):\n{prev_error_text}"
                                )
                            # иначе — молча уходим на следующую итерацию цикла (retry)
            
                except subprocess.TimeoutExpired:
                    self.show_in_listing(f"Превышено время ожидания генерации ({GENERATE_SUBPROCESS_TIMEOUT} сек)")
                except Exception as ex:
                    self.show_in_listing(f"Ошибка выполнения:\n{str(ex)}")

        except Exception as ex:
            self.show_in_listing(f"Общая ошибка:\n{str(ex)}")
        return 0
    
    #------------------------------------------------------------------------------
    # Callback Name: ok_cb
    #------------------------------------------------------------------------------
    def ok_cb(self):
        errorCode = 0
        try:
            errorCode = self.apply_cb()
        except Exception as ex:
            errorCode = 1
            self.theUI.NXMessageBox.Show("Ошибка", NXOpen.NXMessageBox.DialogType.Error, str(ex))
        return errorCode
    
    #------------------------------------------------------------------------------
    # Function Name: GetBlockProperties
    #------------------------------------------------------------------------------
